    cguSection2Desc: "Exchanges, physical interventions, and equipment loans are the exclusive responsibility of the parties involved. Each member agrees to exercise caution and diligence.",
    cguSection3Title: "3. Data Protection & GDPR",
    cguSection3Desc: "Your personal data (name, email, city, skills) is strictly isolated in your secure space and never resold to third parties.",
