    cguTabFull: "ðŸ“œ Testo Giuridico Integrale",
    cguWelcomeIntro: "Benvenuto su Troco! Per garantire una piattaforma sicura, equa e accogliente, ti chiediamo di leggere e approvare le seguenti regole.",
    pillar1Title: "1 Ora = 1 Gettone Troco",
    pillar1Desc: "La regola fondamentale di Troco si basa sulla paritÃ  del tempo condiviso. Un'ora di aiuto o formazione equivale sempre a 1 Gettone Troco, garantendo un'economia collaborativa equa e decentralizzata.",
    pillar2Title: "Sicurezza dei Prestiti e Cauzioni",
    pillar2Desc: "Per ogni prestito di materiale, puÃ² essere richiesta una pre-autorizzazione cauzionale senza addebito immediato, garantendo la restituzione in perfetto stato.",
    pillar3Title: "Tolleranza Zero Frodi e Truffe",
