    pillar6Desc: "Gli scambi, le videochiamate e i messaggi devono svolgersi in un clima cordiale, puntuale e rispettoso della privacy di ciascuno.",
    cguArt1Title: "Articolo 1 â€” Oggetto e Definizione della Piattaforma",
