    cguArt2Title: "Articolo 2 â€” Account e Accuratezza delle Informazioni",
    cguArt2Desc: "L'utente si impegna a fornire informazioni veritiere durante la registrazione, mantenere aggiornato il profilo e creare un solo account per persona fisica.",
    cguArt3Title: "Articolo 3 â€” Regola del Baratto Temporale e Monetizzazione",
    cguArt3Desc: "Il Gettone Troco rappresenta 1 ora di servizio o formazione. L'acquisto di gettoni o boost di visibilitÃ  Ã¨ definitivo conformemente alle normative a tutela del consumatore.",
    cguArt4Title: "Articolo 4 â€” Cauzioni e ResponsabilitÃ  dei Prestiti",
    cguArt4Desc: "Le cauzioni per il prestito di beni materiali costituiscono una garanzia finanziaria pre-autorizzata. In caso di mancata restituzione o danni verificati, l'importo potrÃ  essere addebitato previa mediazione Troco.",
    cguArt5Title: "Articolo 5 â€” Moderazione, Rilevamento e Sanzioni",
